assert set(EN) == set(RU), set(EN) ^ set(RU)
MARK = "## v3.0.0"
for pack in ("resource_packs/Odyssey_Creatures_RP", "behavior_packs/Odyssey_Creatures_BP"):
    for fn, table in (("en_US.lang", EN), ("ru_RU.lang", RU)):
        p = os.path.join(W, pack, "texts", fn)
        txt = open(p, encoding="utf-8").read()
        if MARK in txt: txt = txt[:txt.index(MARK)].rstrip("\n") + "\n"
        # drop older definitions of keys we now own, so v3 wins
        lines = [l for l in txt.split("\n") if not (("=" in l) and l.split("=", 1)[0].strip() in table)]
        out = "\n".join(lines).rstrip("\n") + "\n\n" + MARK + "\n" + "\n".join(f"{k}={v}" for k, v in table.items()) + "\n"
        open(p, "w", encoding="utf-8").write(out)
print("lang keys", len(EN))
